package com.hms.ui;
import com.hms.model.Patient; import com.hms.service.PatientService; import com.hms.util.UiUtil; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.time.LocalDate; import java.util.Objects; import java.util.List;
public class PatientPanel extends JPanel {private final PatientService service;private final JTextField search=new JTextField();private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Reg. No.","Name","Gender","DOB","Phone","Email","Blood"},0);private final JTable table=new JTable(model);private List<Patient> rows=List.of();public PatientPanel(PatientService s){service=s;setLayout(new BorderLayout(8,8));JPanel top=new JPanel(new BorderLayout(5,5));top.add(new JLabel("Search:"),BorderLayout.WEST);top.add(search);JButton go=new JButton("Refresh");go.addActionListener(e->load());JButton add=new JButton("Add patient");add.addActionListener(e->edit(null));JButton edit=new JButton("Edit selected");edit.addActionListener(e->{int i=table.getSelectedRow();if(i>=0)edit(rows.get(i));});JButton del=new JButton("Delete selected");del.addActionListener(e->delete());JPanel buttons=new JPanel();buttons.add(go);buttons.add(add);buttons.add(edit);buttons.add(del);top.add(buttons,BorderLayout.EAST);add(top,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());load();}
 private void load(){try{rows=service.findAll(search.getText());model.setRowCount(0);for(Patient p:rows)model.addRow(new Object[]{p.patientId(),p.registrationNo(),p.fullName(),p.gender(),p.dateOfBirth(),p.phone(),p.email(),p.bloodGroup()});}catch(Exception e){UiUtil.showError(this,e);}}
 private void delete(){int i=table.getSelectedRow();if(i<0)return;if(UiUtil.confirm(this,"Delete this patient?"))try{service.delete(rows.get(i).patientId());load();}catch(Exception e){UiUtil.showError(this,e);}}
 private void edit(Patient old){JTextField reg=new JTextField(old==null?"":old.registrationNo()),name=new JTextField(old==null?"":old.fullName()),dob=new JTextField(old==null?"1990-01-01":old.dateOfBirth().toString()),phone=new JTextField(old==null?"":old.phone()),email=new JTextField(old==null?"":Objects.toString(old.email(),"")),address=new JTextField(old==null?"":Objects.toString(old.address(),"")),blood=new JTextField(old==null?"":Objects.toString(old.bloodGroup(),"")),emergency=new JTextField(old==null?"":Objects.toString(old.emergencyContact(),""));JComboBox<String> gender=new JComboBox<>(new String[]{"Male","Female","Other"});if(old!=null)gender.setSelectedItem(old.gender());JPanel p=UiUtil.formPanel();GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(3,3,3,3);String[] labs={"Registration no.","Full name","Gender","DOB (yyyy-mm-dd)","Phone","Email","Address","Blood group","Emergency contact"};Component[] fields={reg,name,gender,dob,phone,email,address,blood,emergency};for(int i=0;i<labs.length;i++)UiUtil.addField(p,c,i,labs[i],fields[i]);if(JOptionPane.showConfirmDialog(this,p,old==null?"Add patient":"Edit patient",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{Patient x=new Patient(old==null?0:old.patientId(),reg.getText(),name.getText(),(String)gender.getSelectedItem(),LocalDate.parse(dob.getText()),phone.getText(),email.getText(),address.getText(),blood.getText(),emergency.getText());if(old==null)service.save(x);else service.update(x);load();}catch(Exception e){UiUtil.showError(this,e);}}
}
